@register.simple_tag
def icon(name: str, css_class: str = "size-5") -> str:
    path = ICONS.get(name)
    if path is None:
        return ""
    return format_html(
        '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" '
        'stroke="currentColor" class="{}" aria-hidden="true"><path stroke-linecap="round" '
        'stroke-linejoin="round" d="{}"/></svg>',
        css_class,
        mark_safe(path),  # noqa: S308 - static, trusted path data
    )
